head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};
scwin.onpageload = function() {
	scwin.data1 = [
		"0", "A", 1,
		"0", "A", 2,
		"0", "A", 3,
		"0", "B", 4,
		"0", "B", 5,
		"0", "B", 6,
		"0", "B", 7,
		"0", "C", 8,
		"0", "C", 9,
		"0", "C", 10,
		"0", "C", 11
	];
	dataList1.setData(scwin.data1.slice(0));
}
scwin.grid1_ongroupby = function(options) {
	options.groupbyHeader = [{
			inputType: "text",
			value: "header1"
		},
		{
			inputType: "text",
			value: "header2"
		},
		{
			inputType: "text",
			value: "header3"
		}
	]
	options.groupbyFooter = [{
			inputType: "text",
			value: "footer1"
		},
		{
			inputType: "text",
			value: "footer2"
		},
		{
			inputType: "text",
			value: "footer3"
		},
	];
	this.groupby(options);
	return true;
}
scwin.checkMerge = function() {
	var el = ((j) => j.length ? j : $('#mf_grid1_body_tbody tr'))($('#grid1_body_tbody tr')).not(".w2grid_hidedRow").children();
	for (i = 0; i < el.length - 1; i++) {
		if (i % 3 == 0 && i != 0) {
			if (el[i].innerText == "0" || window.getComputedStyle(el[0]).getPropertyValue("border-bottom-width") == "0px") {
				return false;
			}
		} else if (el[0].innerText == "0") {
			return true;
		} else {
			return false;
		}
	}
}
scwin.checkUnMerge = function() {
	var el = ((j) => j.length ? j : $('#mf_grid1_body_tbody tr'))($('#grid1_body_tbody tr')).not(".w2grid_hidedRow").not(".w2grid_lastRow");
	for (i = 1; i < el.length; i++) {
		if (scwin.__getJq($(el)[i]).children()[0].innerText != "0") {
			return false;
		}
	}
	return true;
}
